import { colors } from "@/theme/tokens";
import { logoPath } from "@/theme/logo";

/** Billy app mark: indigo tile with the outlined "Billy" wordmark. Path is generated by scripts/gen-logo.mjs. */
export function Logo({ size = 64, className }: { size?: number; className?: string }) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 100 100"
      width={size}
      height={size}
      role="img"
      aria-label="Billy"
      className={className}
    >
      <rect width="100" height="100" rx="22" fill={colors.ink} />
      <path d={logoPath} fill="#fff" />
    </svg>
  );
}
